CREATE TABLE sections (
  key TEXT PRIMARY KEY,
  position INTEGER NOT NULL,
  data TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE site_config (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  data TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

INSERT INTO sections (key, position, data) VALUES ('hero', 1, '{"heading":"Soluciones integrales en *gestión sanitaria*","subheading":"La salud, bien gestionada a través de una sola empresa. Planificamos, organizamos y dirigimos recursos para maximizar la calidad y eficiencia.","image":{"url":"/media/hero.png","width":800,"height":600,"alternativeText":"Imagen Hero"},"link":{"href":"https://cal.com/enlacesalud/15min","label":"Agendar una meet"}}');
INSERT INTO sections (key, position, data) VALUES ('about', 2, '{"tagline":"Nosotros","heading":"Quiénes Somos","description":"Somos una empresa de soluciones integrales que opera bajo un innovador modelo de gerenciamiento sanitario. Nuestro objetivo principal es centralizar, coordinar y optimizar servicios, integrando la gestión comercial, los recursos humanos y la infraestructura tecnológica necesaria.\n\nEntendemos la salud como un ecosistema complejo que requiere precisión y eficiencia. Por ello, actuamos como un nexo estratégico entre las necesidades de nuestros clientes y las soluciones médicas más adecuadas.","image":{"url":"/media/about.jpg","alternativeText":"","width":800,"height":600}}');
INSERT INTO sections (key, position, data) VALUES ('services', 3, '{"tagline":"Servicios","heading":"Qué Hacemos","subheading":"Brindamos un abanico de servicios diseñados para cubrir todas las necesidades sanitarias.","service_cards":[{"id":"1","iconName":"TruckMedical","title":"Emergencias Médicas","description":"Atención inmediata de urgencias y emergencias con unidades de terapia intensiva móvil totalmente equipadas."},{"id":"2","iconName":"VanShuttle","title":"Traslados Sanitarios","description":"Transporte de pacientes de baja, media y alta complejidad, garantizando seguridad y confort en cada trayecto."},{"id":"3","iconName":"CalendarCheck","title":"Cobertura de Eventos","description":"Protección médica integral en eventos deportivos, corporativos y masivos con personal especializado."},{"id":"4","iconName":"TruckMonster","title":"Cobertura de Alta Exigencia","description":"Unidades 4x4 preparadas para acceder a zonas remotas, obras, campos y terrenos difíciles."},{"id":"5","iconName":"BedPulse","title":"Internación Domiciliaria","description":"Llevamos la calidad hospitalaria al hogar, facilitando la recuperación rodeado de los afectos."},{"id":"6","iconName":"UserDoctor","title":"Medicina Laboral","description":"Gestión integral de la salud ocupacional, exámenes y control de ausentismo para empresas."},{"id":"7","iconName":"HeartPulse","title":"Atención Integral de la Salud","description":"Enfoque holístico de la salud, coordinando diagnósticos, tratamientos y seguimiento personalizado."},{"id":"8","iconName":"ClipboardList","title":"Gerenciamiento y Coordinación","description":"Administración eficiente de recursos y coordinación de redes prestacionales sanitarias."},{"id":"9","iconName":"PuzzlePiece","title":"Prestaciones a Medida","description":"Soluciones de salud personalizadas y flexibles, adaptadas a las necesidades específicas de cada organización."},{"id":"10","iconName":"MapLocationDot","title":"Cobertura Nacional","description":"Red de servicios con alcance local, provincial y nacional para estar donde nos necesites."},{"id":"11","iconName":"SuitcaseMedical","title":"Asistencia al Viajero","description":"Tranquilidad en tus viajes y cuidados especiales adaptados para pacientes en tránsito o estadía."}]}');
INSERT INTO sections (key, position, data) VALUES ('health-management', 4, '{"tagline":"Nuestro Modelo","heading":"Gerenciadora de Salud","description":"Actuamos como un <b>único punto de contacto</b>, simplificando la complejidad del sistema sanitario para su empresa.","benefitsTitle":"Beneficios Clave","benefits":"Optimización de tiempos de respuesta\nReducción de costos operativos\nCalidad médica estandarizada\nTrazabilidad total de prestaciones","statNumber":"100%","statLabel":"Gestión Centralizada","image":{"url":"/media/health-management.jpg","alternativeText":""}}');
INSERT INTO sections (key, position, data) VALUES ('philosophy', 5, '{"heading":"Filosofía Corporativa","subheading":"Nuestros pilares fundamentales que guían cada acción.","missionTitle":"Misión","missionText":"Brindar soluciones integrales mediante una gestión eficiente, humana y profesional, adaptándonos a las necesidades específicas de cada cliente.","visionTitle":"Visión","visionText":"Ser el referente en gerenciamiento sanitario, reconocidos por nuestra capacidad de respuesta, eficiencia y confiabilidad en el mercado.","featuredTitle":"Compromiso Humano","featuredText":"La empatía es el motor de nuestra excelencia operativa.","featuredImage":{"url":"/media/philosophy-featured.jpg","alternativeText":""},"pillars":[{"id":"1","iconName":"Heart","title":"Compromiso con la vida","description":"La integridad y salud de las personas es nuestra prioridad absoluta."},{"id":"2","iconName":"Award","title":"Profesionalismo","description":"Equipo altamente capacitado y en constante formación."},{"id":"3","iconName":"Zap","title":"Eficiencia operativa","description":"Procesos optimizados para respuestas rápidas y efectivas."},{"id":"4","iconName":"ShieldCheck","title":"Transparencia","description":"Claridad y honestidad en cada gestión y reporte."}]}');
INSERT INTO sections (key, position, data) VALUES ('target-audience', 6, '{"heading":"Público Objetivo","cards":[{"id":"1","iconName":"Building","label":"Empresas y Organizaciones"},{"id":"2","iconName":"BriefcaseMedical","label":"Obras Sociales y Prepagas"},{"id":"3","iconName":"andHoldingMedical","label":"Financiadores de Salud"},{"id":"4","iconName":"Landmark","label":"Instituciones Públicas y Privadas"},{"id":"5","iconName":"Users","label":"Comunidades y particulares"}]}');
INSERT INTO sections (key, position, data) VALUES ('contact_section', 7, '{"title":"Contacto","description":"Estamos aquí para ayudarte. Contáctanos y responderemos tus consultas a la brevedad.","buttonLabel":"Enviar Mensaje","successMessage":"¡Mensaje enviado con éxito!"}');
